    public static string Format(string key,string lang,params object[] args)
    {
        var template=T(key,lang);
        try{return string.Format(template,args);}catch{return template;}
    }

    public static string T(string value,string lang)
    {
        if(string.IsNullOrWhiteSpace(value))return value;
        var shortcut=value.IndexOf("    ",StringComparison.Ordinal);
        if(shortcut>0)return T(value[..shortcut],lang)+value[shortcut..];
        var prefix="";var core=value;
        if(value.Length>=3&&value[1]==' '&&value[2]==' '&&!char.IsLetterOrDigit(value[0]))
        {
            prefix=value[..3];core=value[3..];
        }
        var key=FindKey(core);
        if(string.IsNullOrEmpty(key))return value;
        var translated=lang=="zh-CN"?Words[key].cn:lang=="en-US"?Words[key].en:key;
        if(core.Length>key.Length&&core.StartsWith(key+" ",StringComparison.Ordinal))translated+=core[key.Length..];
        return prefix+translated;
    }
    public static string DefaultTitle(NestKind kind)=>DefaultWidgetTitles.GetValueOrDefault(kind,"新小工具");
    public static string DisplayTitle(NestModel model,string lang)
    {
        var key=DefaultTitle(model.Kind);
        if(IsDefaultTitle(model.Title,model.Kind))return T(key,lang);
        return model.Title;
    }
    static bool IsDefaultTitle(string title,NestKind kind)
    {
        if(string.IsNullOrWhiteSpace(title))return true;
        var key=DefaultTitle(kind);
        var candidates=new HashSet<string>(StringComparer.OrdinalIgnoreCase){key,T(key,"zh-TW"),T(key,"zh-CN"),T(key,"en-US"),"新小工具",T("新小工具","zh-CN"),T("新小工具","en-US")};
        if(kind==NestKind.Note)candidates.UnionWith(["BeeX 便箋","靈感便箋","靈感箋"]);
        if(kind==NestKind.Todo)candidates.UnionWith(["今日待辦","BeeX 待辦","今日任務板","任務板"]);
        if(kind==NestKind.Capture)candidates.UnionWith(["Capture","Quick Capture","拾光記"]);
        if(kind==NestKind.Music)candidates.UnionWith(["音樂控制","系統媒體控制","聲音卡"]);
        if(kind==NestKind.Clock)candidates.UnionWith(["現在時間","時刻牌"]);
        if(kind==NestKind.Weather)candidates.UnionWith(["BeeX 天氣","氣象牌"]);
        if(kind==NestKind.Tags)candidates.Add("星標集");
        if(kind==NestKind.SystemMonitor)candidates.Add("脈衝儀表");
        if(kind==NestKind.Countdown)candidates.Add("倒數日");
        if(kind==NestKind.Launcher)candidates.Add("星門搜尋");
        if(kind==NestKind.WorkTimer)candidates.UnionWith(["牛馬下班鐘","下班羅盤","牛馬班表"]);
        return candidates.Contains(title.Trim());
    }
    static string FindKey(string value)
    {
        if(Words.ContainsKey(value))return value;
        foreach(var item in Words)
            if(item.Value.cn==value||item.Value.en==value)return item.Key;
        foreach(var item in Words.OrderByDescending(x=>x.Key.Length))
            if(value.StartsWith(item.Key+" ",StringComparison.Ordinal)||value.StartsWith(item.Value.cn+" ",StringComparison.Ordinal)||value.StartsWith(item.Value.en+" ",StringComparison.Ordinal))
                return item.Key;
        return "";
    }
    public static void Apply(DependencyObject? root,string lang)
    {
        if(root==null)return;
        if(root is Window w)w.Title=T(w.Title,lang);
        if(root is TextBlock t)t.Text=T(t.Text,lang);
        if(root is ContentControl c&&c.Content is string s)c.Content=T(s,lang);
        if(root is FrameworkElement f&&f.ToolTip is string tip)f.ToolTip=T(tip,lang);
        if(root is System.Windows.Controls.MenuItem mi&&mi.Header is string header)mi.Header=T(header,lang);
        if(root is ItemsControl items)foreach(var item in items.Items)if(item is DependencyObject d)Apply(d,lang);
        if(root is ContentControl cc&&cc.Content is DependencyObject content)Apply(content,lang);
        if(root is System.Windows.Controls.Primitives.Popup popup&&popup.Child!=null)Apply(popup.Child,lang);
        for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)Apply(VisualTreeHelper.GetChild(root,i),lang);
        if(root is FrameworkElement fe&&fe.ContextMenu!=null)Apply(fe.ContextMenu,lang);
    }
    public static void ApplyFont(DependencyObject? root,string family,double size)
    {
        if(root==null)return;
        var font=new FontFamily(family);
        if(root is System.Windows.Controls.Control control&&!IsIconOnly(control)){control.FontFamily=font;control.FontSize=size;}
        if(root is TextBlock text&&!IsIconText(text)){text.FontFamily=font;if(text.FontSize<=18)text.FontSize=Math.Max(10,size);}
        if(root is ContentControl cc&&cc.Content is DependencyObject content)ApplyFont(content,family,size);
        if(root is ItemsControl items)foreach(var item in items.Items)if(item is DependencyObject d)ApplyFont(d,family,size);
        if(root is System.Windows.Controls.Primitives.Popup popup&&popup.Child!=null)ApplyFont(popup.Child,family,size);
        for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)ApplyFont(VisualTreeHelper.GetChild(root,i),family,size);
        if(root is FrameworkElement fe&&fe.ContextMenu!=null)ApplyFont(fe.ContextMenu,family,size);
    }
    static bool IsIconOnly(object element)
    {
        if(element is System.Windows.Controls.Control c&&c.FontFamily.Source.Contains("Icon",StringComparison.OrdinalIgnoreCase))return true;
        if(element is ContentControl cc&&cc.Content is string s)
            return s.Length<=2&&s.Any(ch=>!char.IsLetterOrDigit(ch)&&!char.IsWhiteSpace(ch));
        return false;
    }
    static bool IsIconText(TextBlock text)=>text.FontFamily.Source.Contains("Icon",StringComparison.OrdinalIgnoreCase);
}
